"""Window layout and the exact mixed-radix universe enumeration.

Cells are flattened slot major and then in field order.  Universe indices
enumerate that flattening lexicographically by *domain position* (numeric gaps
are irrelevant), so index 0 is the all-smallest-values window and the last index
is the all-largest-values window.  This module is dependency-free: both the
vectorised engine and the pure-Python engine share one enumeration.
"""
from __future__ import annotations

from typing import Any, Iterable, Mapping, Sequence


class WindowLayout:
    """Declared Cartesian universe of one job plus its cell addressing."""

    def __init__(self, fields: Sequence[Mapping[str, Any]], slots: int) -> None:
        self.slots = int(slots)
        self.fields = [dict(field) for field in fields]
        self.field_count = len(self.fields)
        self.field_names = [str(field["name"]) for field in self.fields]
        self.field_index = {name: index for index, name in enumerate(self.field_names)}
        self.field_types = [str(field["type"]) for field in self.fields]
        self.field_domains = [[int(value) for value in field["domain"]] for field in self.fields]
        self.value_positions = [
            {value: position for position, value in enumerate(domain)}
            for domain in self.field_domains
        ]
        self.cell_field = [index for _ in range(self.slots) for index in range(self.field_count)]
        self.cell_count = len(self.cell_field)
        self.cell_sizes = [len(self.field_domains[field]) for field in self.cell_field]

        total = 1
        for size in self.cell_sizes:
            total *= size
        self.size = int(total)

        strides = [1] * self.cell_count
        accumulator = 1
        for cell in range(self.cell_count - 1, -1, -1):
            strides[cell] = accumulator
            accumulator *= self.cell_sizes[cell]
        self.cell_strides = strides

    # ------------------------------------------------------------------ layout
    def cell_of(self, ref: Sequence[Any]) -> int:
        """Cell position of a ``[slot, field_name]`` reference."""
        return int(ref[0]) * self.field_count + self.field_index[str(ref[1])]

    def field_cells(self, name: str) -> list[int]:
        """Cells of every slot of one field, in slot order."""
        index = self.field_index[str(name)]
        return [slot * self.field_count + index for slot in range(self.slots)]

    def field_of_cell(self, cell: int) -> int:
        return self.cell_field[cell]

    def domain_of_cell(self, cell: int) -> list[int]:
        return self.field_domains[self.cell_field[cell]]

    def size_of_cell(self, cell: int) -> int:
        return self.cell_sizes[cell]

    def stride_of_cell(self, cell: int) -> int:
        return self.cell_strides[cell]

    # --------------------------------------------------------------- addresses
    def position_of_value(self, cell: int, value: int) -> int:
        """Domain position of a declared value of one cell."""
        return self.value_positions[self.cell_field[cell]][int(value)]

    def encode(self, flat: Iterable[int]) -> int:
        """Universe index of one flattened window (cell order)."""
        index = 0
        for cell, value in enumerate(flat):
            index += self.position_of_value(cell, value) * self.cell_strides[cell]
        return index

    def encode_window(self, window: Sequence[Sequence[int]]) -> int:
        """Universe index of one window given as K rows of field values."""
        flat = [value for row in window for value in row]
        return self.encode(flat)

    def decode(self, index: int) -> list[int]:
        """Flattened cell values of one universe index."""
        remainder = int(index)
        values = []
        for cell in range(self.cell_count):
            position, remainder = divmod(remainder, self.cell_strides[cell])
            values.append(self.domain_of_cell(cell)[position])
        return values

    def decode_window(self, index: int) -> list[list[int]]:
        """Window rows (slot major, field order) of one universe index."""
        flat = self.decode(index)
        width = self.field_count
        return [flat[slot * width:(slot + 1) * width] for slot in range(self.slots)]

    # ------------------------------------------------------------------- masks
    def cell_block_pattern(self, cell: int) -> tuple[int, int, int]:
        """``(stride, size, repetitions)`` of one cell's periodic block pattern."""
        stride = self.cell_strides[cell]
        size = self.cell_sizes[cell]
        return stride, size, self.size // (stride * size)

    def cell_equal_mask(self, cell: int, position: int) -> int:
        """Universe bitset of all windows whose cell holds that domain position."""
        stride, size, repetitions = self.cell_block_pattern(cell)
        block = ((1 << stride) - 1) << (position * stride)
        period = size * stride
        if repetitions == 1:
            return block
        return block * (((1 << self.size) - 1) // ((1 << period) - 1))

    def value_mask(self, cell: int, truth_by_position: Sequence[bool]) -> int:
        """Universe bitset of the windows whose cell value satisfies ``truth``."""
        stride, size, repetitions = self.cell_block_pattern(cell)
        period_bits = size * stride
        nbytes = (period_bits + 7) // 8
        period = bytearray(nbytes)
        for position, holds in enumerate(truth_by_position):
            if holds:
                set_bit_range(period, position * stride, stride)
        value = int.from_bytes(period, "little")
        if repetitions == 1:
            return value
        return value * (((1 << self.size) - 1) // ((1 << period_bits) - 1))


def set_bit_range(buffer: bytearray, start: int, count: int) -> None:
    """Set ``count`` consecutive bits starting at bit index ``start`` (little endian)."""
    if count <= 0:
        return
    end = start + count
    first = start >> 3
    last = (end - 1) >> 3
    if first == last:
        buffer[first] |= ((1 << count) - 1) << (start & 7)
        return
    buffer[first] |= 0xFF << (start & 7)
    if last > first + 1:
        buffer[first + 1:last] = b"\xff" * (last - first - 1)
    buffer[last] |= (1 << (end - (last << 3))) - 1


def pack_flags(flags: Iterable[bool], length: int) -> int:
    """Exact little-endian bitset of an iterable of ``length`` truth values."""
    buffer = bytearray((length + 7) // 8)
    for index, holds in enumerate(flags):
        if holds:
            buffer[index >> 3] |= 1 << (index & 7)
    return int.from_bytes(buffer, "little")


def iter_set_bits(mask: int, nbytes: int) -> Iterable[int]:
    """Ascending positions of the set bits of a nonnegative bitset."""
    buffer = mask.to_bytes(nbytes, "little")
    for byte_index, byte in enumerate(buffer):
        if not byte:
            continue
        base = byte_index << 3
        while byte:
            low = byte & -byte
            yield base + low.bit_length() - 1
            byte ^= low
